class Solution {
    public int longestFresh(String s) {
        int n = s.length(), best = 0;
        for (int i = 0; i < n; i++) {
            boolean[] seen = new boolean[128];
            int j = i;
            while (j < n && !seen[s.charAt(j)]) seen[s.charAt(j++)] = true;
            best = Math.max(best, j - i);
        }
        return best;
    }
}

