int longestFresh(char* s) {
    int last[128], left = 0, best = 0, n = strlen(s);
    for (int c = 0; c < 128; c++) last[c] = -1;
    for (int i = 0; i < n; i++) {
        int c = s[i];
        if (last[c] >= left) left = last[c] + 1;
        last[c] = i;
        if (i - left + 1 > best) best = i - left + 1;
    }
    return best;
}
